  const [loading, setLoading] = useState(true);
  const load = () => { setLoading(true); const params = new URLSearchParams({ status, page: String(page), pageSize: "50" }); if (search) params.set("search", search); adminFetch<{ events: AdminEventRecord[]; pagination?: { total?: number } }>(`/admin/events?${params}`).then((body) => { setEvents(body.events || []); setTotal(body.pagination?.total || 0); }).catch((error) => onNotice(error.message)).finally(() => setLoading(false)); };
